import{_ as o,J as r,b as t,e as n,a8 as i,f as a,L as d}from"./chunks/framework.BXWQBDlf.js";const m=JSON.parse('{"title":"GR32_Brushes","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Brushes","entity":"GR32_Brushes","kind":"Unit","summary":"Provides vector polygon brush effects including solid filling, stroking, growing, dashing, and nested brush pipelines.","title":"GR32_Brushes","date":1789502822000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Brushes/index.md","filePath":"api/GR32_Brushes/index.md","lastUpdated":1789502822000,"timestamp":1789502822000,"datetime":"2026-09-15T20:07:02.000Z"}'),l={name:"api/GR32_Brushes/index.md"};function c(h,e,u,p,g,B){const s=r("ApiMembers");return t(),n("div",null,[e[0]||(e[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Brushes</code> unit provides a modular vector brush architecture for rendering vector paths and polygons in Graphics32.</p><p>Brushes encapsulate polygon drawing behaviors (such as outline stroking, polygon expansion/shrinking, dashed pattern generation, and solid color/filler assignment) and can be chained together in brush collections or composite nested brushes.</p><p>Key classes and types in <code>GR32_Brushes</code> include:</p><ul><li><strong>Brush Collection</strong>: <a href="/api/GR32_Brushes/TBrushCollection/"><code>TBrushCollection</code></a> manages an ordered list of brush instances assigned to an owner object.</li><li><strong>Base Class</strong>: <a href="/api/GR32_Brushes/TCustomBrush/"><code>TCustomBrush</code></a> defines the fundamental interface and pipeline methods for vector path processing and rendering (<code>PolygonFS</code>, <code>PolyPolygonFS</code>, <code>PolyPolygonMixedFS</code>).</li><li><strong>Solid Brush</strong>: <a href="/api/GR32_Brushes/TSolidBrush/"><code>TSolidBrush</code></a> applies fill color, fill mode, or custom polygon fillers (<a href="/api/GR32_Polygons/TCustomPolygonFiller/"><code>TCustomPolygonFiller</code></a>) to vector shapes.</li><li><strong>Nested Brush</strong>: <a href="/api/GR32_Brushes/TNestedBrush/"><code>TNestedBrush</code></a> contains its own child <a href="/api/GR32_Brushes/TBrushCollection/"><code>TBrushCollection</code></a>, executing multiple brush effects sequentially on the same geometry.</li><li><strong>Stroke Brush</strong>: <a href="/api/GR32_Brushes/TStrokeBrush/"><code>TStrokeBrush</code></a> converts closed or open vector paths into stroked outlines using specified line widths, join styles, end styles, and miter limits.</li><li><strong>Grow Brush</strong>: <a href="/api/GR32_Brushes/TGrowBrush/"><code>TGrowBrush</code></a> inflates or deflates polygon boundaries by a floating-point grow amount.</li><li><strong>Dashed Brush</strong>: <a href="/api/GR32_Brushes/TDashedBrush/"><code>TDashedBrush</code></a> splits vector outlines into dashed line segments using custom dash pattern arrays and offsets before stroking.</li></ul>',5)),a("p",null,[d(s,{type:"members"})])])}const _=o(l,[["render",c]]);export{m as __pageData,_ as default};
